SELECT "frpm"."School Name" AS "School Name", "schools"."fundingtype" AS "fundingtype", AVG("satscores"."avgscrmath") AS "avg_math_score" FROM "frpm" JOIN "satscores" ON "frpm"."cdscode" = "satscores"."cds" JOIN "schools" ON "frpm"."cdscode" = "schools"."cdscode" WHERE "frpm"."County Name" = 'Riverside' AND "satscores"."avgscrmath" > 400 GROUP BY "frpm"."School Name", "schools"."fundingtype" ORDER BY "avg_math_score" DESC;
